CREATE TABLE IF NOT EXISTS "aprendiz" (
	"Id_Aprendiz" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"Tipo_Documento" VARCHAR(255) NOT NULL,
	"Documento" VARCHAR(255) NOT NULL UNIQUE,
	"Nombre" VARCHAR(255) NOT NULL,
	"Apellido" VARCHAR(255) NOT NULL,
	"Estado" VARCHAR(255) NOT NULL,
	"Id_Ficha" INTEGER NOT NULL,
	PRIMARY KEY("Id_Aprendiz")
);




CREATE TABLE IF NOT EXISTS "programa" (
	"Id_Programa" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"Nombre" VARCHAR(255) NOT NULL UNIQUE,
	"Modalidad" VARCHAR(255),
	"Codigo" VARCHAR(255) NOT NULL,
	"Version" VARCHAR(255) NOT NULL,
	PRIMARY KEY("Id_Programa")
);




CREATE TABLE IF NOT EXISTS "ficha" (
	"Id_Ficha" INTEGER NOT NULL UNIQUE,
	"Jornada" VARCHAR(255) NOT NULL,
	"Id_Programa" INTEGER NOT NULL,
	"Id_Competencia" INTEGER NOT NULL,
	PRIMARY KEY("Id_Ficha")
);




CREATE TABLE IF NOT EXISTS "competencia" (
	"Id_Competencia" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"Codigo" VARCHAR(255) NOT NULL,
	"Id_Resultado" INTEGER NOT NULL,
	PRIMARY KEY("Id_Competencia")
);




CREATE TABLE IF NOT EXISTS "resultados" (
	"Id_Resultado" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"Codigo" INTEGER NOT NULL UNIQUE,
	PRIMARY KEY("Id_Resultado")
);




CREATE TABLE IF NOT EXISTS "juicios_evaluativos" (
	"Id_Juicio" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"Id_Resultado" INTEGER NOT NULL,
	"Id_Aprendiz" INTEGER NOT NULL,
	"Estado" INTEGER NOT NULL,
	"Id_Funcionario" INTEGER NOT NULL,
	"Fecha" DATE,
	"Hora" TIMESTAMP,
	PRIMARY KEY("Id_Juicio")
);




CREATE TABLE IF NOT EXISTS "funcionario" (
	"Id_Funcionario" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"Tipo_Documento" VARCHAR(255) NOT NULL,
	"Documento" NUMERIC NOT NULL UNIQUE,
	"Nombre" VARCHAR(255) NOT NULL,
	"Apellido" VARCHAR(255) NOT NULL,
	PRIMARY KEY("Id_Funcionario")
);



ALTER TABLE "ficha"
ADD FOREIGN KEY("Id_Ficha") REFERENCES "aprendiz"("Id_Ficha")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "programa"
ADD FOREIGN KEY("Id_Programa") REFERENCES "ficha"("Id_Programa")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "competencia"
ADD FOREIGN KEY("Id_Competencia") REFERENCES "ficha"("Id_Competencia")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "competencia"
ADD FOREIGN KEY("Id_Resultado") REFERENCES "resultados"("Id_Resultado")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "juicios_evaluativos"
ADD FOREIGN KEY("Id_Resultado") REFERENCES "resultados"("Id_Resultado")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "juicios_evaluativos"
ADD FOREIGN KEY("Id_Aprendiz") REFERENCES "aprendiz"("Id_Aprendiz")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "funcionario"
ADD FOREIGN KEY("Id_Funcionario") REFERENCES "juicios_evaluativos"("Id_Funcionario")
ON UPDATE NO ACTION ON DELETE NO ACTION;